---@class BaseSetting
local BaseSetting = Class("BaseSetting")

---__init
---@param self BaseSetting
---@param filePaths table
---@param voName string vo名称
local function __init(self, filePaths, voName)
    self.settingPaths = {}
    self.__reloadCount = 0
    --self.header2Index = {}
    ---@type table<string, SettingRefBase>
    self.id2vo = {} -- id:vo
    self.voName = voName
    for i, v in pairs(filePaths) do
        local targetPath = string.format("%s%s", filePaths[i], appEngine.GetConfig("Engine", "AssetBundleExt"))
        table.insert(self.settingPaths, targetPath)
    end
end

---__delete
---@param self BaseSetting
local function __delete(self)
    self.settingPaths = nil
    self.__reloadCount = nil
    self.id2vo = nil
    self.voName = nil
end

---Count
---@param self BaseSetting
local function Count(self)
    local count = 0
    local tableFile = nil
    for i = 1, table.length(self.settingPaths) do
        local tableFilePath = self.settingPaths[i]
        ---@type TableML.TableFile
        tableFile = settingModule.Get(tableFilePath, true) --不缓存数据
        if tableFile then
            count = count + tableFile:GetRowCount()
        end
    end
    return count
end

---ForceReloadAll
---@param self BaseSetting
local function ForceReloadAll(self)
    self:__ReloadAll(false)
end

---ReloadAll
---@param self BaseSetting
local function ReloadAll(self)
    if self.__reloadCount == 0 then
        self:__ReloadAll(true)
    end
end

