---Get
---@param self BaseSetting
---@param primaryKey string
---@return SettingRefBase
local function Get(self, primaryKey)
    primaryKey = checkString(primaryKey)
    local vo = self.id2vo[primaryKey]
    if isNull(vo) then
        local tableFile = nil
        local tt = import(string.format("Game.Setting.Vo.%s", self.voName))
        for i = 1, table.length(self.settingPaths) do
            local tableFilePath = self.settingPaths[i]
            ---@type TableML.TableFile
            tableFile = settingModule.Get(tableFilePath, true) --不缓存数据
            if tableFile and tableFile:HasPrimaryKey(primaryKey) then
                vo = tt.New()
                vo:FillVo(tableFile:GetByPrimaryKey(primaryKey))
                self.id2vo[primaryKey] = vo
            end
        end
    end
    return vo
end

---GetAll
---@param self BaseSetting
---@return table
local function GetAll(self)
    local t = {}
    local tableFile = nil
    local vo = nil
    local tt = import(string.format("Game.Setting.Vo.%s", self.voName))
    for i = 1, table.length(self.settingPaths) do
        local tableFilePath = self.settingPaths[i]
        ---@type TableML.TableFile
        tableFile = settingModule.Get(tableFilePath, true) --不缓存数据
        if tableFile then
            for _, row in pairs(tableFile) do
                local pk = checkString(row:GetPrimaryKey())
                ---@type SettingRefBase
                if not isSet(self.id2vo, pk) then
                    vo = tt.New()
                    vo:FillVo(row)
                    self.id2vo[pk] = vo
                    table.insert(t, vo)
                else
                    vo = self.id2vo[pk]
                    table.insert(t, vo)
                end
            end
        end
    end
    return t
end

