---@class SettingMgr
---@field GetInstance fun(self:SettingMgr):SettingMgr
local SettingMgr = Class("SettingMgr", Singleton)

function SettingMgr:__init(...)
    --self.__reloadHandler = Bind(self, self.__ReloadLuaSetting)
    --settingModule.OnReloaded = self.__reloadHandler
    ---@type BaseSetting[]
    self.settings = {} --缓存所有配表 path:SettingVo类
    ---@type table<string, string[]>
    self.paths = {} --路径信息列表
    self.isFinish = false
end

---Get 得到tableFile类型的类
---@param path string
---@param useCache boolean
---@return TableML.TableFile
function SettingMgr:Get(path, useCache)
    if isNull(useCache) then
        useCache = true
    end
    return settingModule.Get(path, useCache)
end

function SettingMgr:FreshSettingPaths()
    local entry = appEngine.GetConfig("Engine.Setting", "SettingNames")
    ---@type TableML.TableFile
    local tableFile = settingModule.Get(entry)
    self.paths = {} ---重置下
    for i, row in pairs(tableFile) do
        ---@type TableML.TableFileRow
        local row = row
        local id  = tostring(row:GetPrimaryKey())
        if not string.isEmpty(id) then
            local path = row:Get("export")
            local storeKey = path
            if string.contains(storeKey, "+") then
                storeKey = storeKey.sub(2)
            end
            if self.paths[storeKey] then
                table.insert(self.paths[storeKey], storeKey)
            else
                self.paths[storeKey] = {path}
            end
        end
    end
end

---GetSetting
---@param path string
---@param voName string
---@param callback fun(path:string, voName:string):void
---@return BaseSetting
function SettingMgr:GetSetting(path, voName, callback)
    if not self.isFinish then
        self.isFinish = true
        self:FreshSettingPaths()
    end
    ---@type BaseSetting
    local setting = nil
    if not isSet(self.settings, path) then
        local settingPaths = self.paths[path]
        if isNull(settingPaths) then
            settingPaths = {path}
        end
        setting = BaseSetting.New(settingPaths, voName)
        self.settings[path] = setting
    else
        setting = self.settings[path]
    end
    if not isNull(setting) then
        setting:ReloadAll()
        if not isNull(callback) and type(callback) == 'function' then
            callback(path, voName)
        end
    end
    return setting
end

function SettingMgr:ReloadSettings(cb)
    for i, setting in pairs(self.settings) do
        setting.id2vo = {}
        setting:ForceReloadAll()
        -- if cb then
        --     cb()
        -- end
    end
    print("reload setting succeed")
end

